#if !SCREENBRIDGE_STRIPPED
import Foundation

public enum WireProtocol {
    /// Incremented on breaking changes to framing or message semantics.
    public static let version = 1
    public static let serviceType = "_screenbridge._tcp"
    /// TXT key holding the public receiver ID. TXT records never carry secrets.
    public static let txtReceiverIDKey = "rid"
    public static let txtVersionKey = "v"
    public static let connectionResourceName = "ScreenBridgeConnection"
    public static let connectionResourceExtension = "json"
}

/// Generated by the build integration and copied into the app bundle (Debug only).
/// Contains a development credential; it must never be committed or shipped.
public struct ConnectionConfig: Codable, Sendable, Equatable {
    public var schemaVersion: Int
    public var receiverID: String
    public var receiverName: String
    public var serviceType: String
    public var credentialID: String
    /// Base64-encoded 32-byte pre-shared key for TLS-PSK.
    public var pskBase64: String
    public var projectID: String
    public var projectName: String
    /// Absolute project root on the building Mac. Used only to turn `#filePath`
    /// values into repository-relative paths; never exported in reports.
    public var projectRoot: String
    public var appBundleIdentifier: String
    public var build: BuildInfo
    public var generatedAt: Date

    public static let currentSchemaVersion = 1

    public init(receiverID: String, receiverName: String, credentialID: String, pskBase64: String, projectID: String, projectName: String, projectRoot: String, appBundleIdentifier: String, build: BuildInfo, generatedAt: Date = Date()) {
        self.schemaVersion = Self.currentSchemaVersion
        self.receiverID = receiverID
        self.receiverName = receiverName
        self.serviceType = WireProtocol.serviceType
        self.credentialID = credentialID
        self.pskBase64 = pskBase64
        self.projectID = projectID
        self.projectName = projectName
        self.projectRoot = projectRoot
        self.appBundleIdentifier = appBundleIdentifier
        self.build = build
        self.generatedAt = generatedAt
    }

    public var psk: Data? { Data(base64Encoded: pskBase64) }

    public static func decode(_ data: Data) throws -> ConnectionConfig {
        let c = try ReportCoding.decoder().decode(ConnectionConfig.self, from: data)
        guard c.schemaVersion == currentSchemaVersion else {
            throw ReportSchemaError.incompatibleMajor(found: c.schemaVersion, supported: currentSchemaVersion)
        }
        return c
    }
}

public enum WireMessageType: String, Codable, Sendable {
    case hello
    case helloAck
    case report
    case reportAck
    case revealSource
    case revealResult
    case error
}

public struct Hello: Codable, Sendable, Equatable {
    public var credentialID: String
    /// The receiver the app expects. The receiver rejects mismatches.
    public var receiverID: String
    public var projectID: String
    public var appBundleIdentifier: String
    public var appName: String
    public var buildID: String?
    public var deviceModel: String
    public var systemVersion: String
    public var isSimulator: Bool

    public init(credentialID: String, receiverID: String, projectID: String, appBundleIdentifier: String, appName: String, buildID: String?, deviceModel: String, systemVersion: String, isSimulator: Bool) {
        self.credentialID = credentialID
        self.receiverID = receiverID
        self.projectID = projectID
        self.appBundleIdentifier = appBundleIdentifier
        self.appName = appName
        self.buildID = buildID
        self.deviceModel = deviceModel
        self.systemVersion = systemVersion
        self.isSimulator = isSimulator
    }
}

public struct HelloAck: Codable, Sendable, Equatable {
    public var accepted: Bool
    public var receiverID: String
    public var receiverName: String
    public var reason: String?

    public init(accepted: Bool, receiverID: String, receiverName: String, reason: String? = nil) {
        self.accepted = accepted
        self.receiverID = receiverID
        self.receiverName = receiverName
        self.reason = reason
    }
}

public struct ReportAck: Codable, Sendable, Equatable {
    public var reportID: String
    /// True when the receiver already had this report and did not store it again.
    public var duplicate: Bool
    public var receivedAt: Date

    public init(reportID: String, duplicate: Bool, receivedAt: Date) {
        self.reportID = reportID
        self.duplicate = duplicate
        self.receivedAt = receivedAt
    }
}

public struct RevealRequest: Codable, Sendable, Equatable {
    public var projectID: String
    /// Repository-relative path.
    public var path: String
    public var line: Int?

    public init(projectID: String, path: String, line: Int?) {
        self.projectID = projectID
        self.path = path
        self.line = line
    }
}

public struct RevealResult: Codable, Sendable, Equatable {
    public var opened: Bool
    public var message: String

    public init(opened: Bool, message: String) {
        self.opened = opened
        self.message = message
    }
}

public struct WireError: Codable, Sendable, Equatable {
    public var code: String
    public var message: String

    public init(code: String, message: String) {
        self.code = code
        self.message = message
    }
}

public struct PartDescriptor: Codable, Sendable, Equatable {
    public var name: String
    public var length: Int

    public init(name: String, length: Int) {
        self.name = name
        self.length = length
    }
}

/// JSON header of a frame. Exactly one payload field is set, matching `type`.
public struct WireEnvelope: Codable, Sendable, Equatable {
    public var type: WireMessageType
    public var protocolVersion: Int
    public var hello: Hello?
    public var helloAck: HelloAck?
    public var report: DebugReport?
    /// Binary parts concatenated in the frame body, in order.
    public var parts: [PartDescriptor]?
    public var reportAck: ReportAck?
    public var reveal: RevealRequest?
    public var revealResult: RevealResult?
    public var error: WireError?

    public init(type: WireMessageType) {
        self.type = type
        self.protocolVersion = WireProtocol.version
    }

    public static func hello(_ h: Hello) -> WireEnvelope { var e = WireEnvelope(type: .hello); e.hello = h; return e }
    public static func helloAck(_ h: HelloAck) -> WireEnvelope { var e = WireEnvelope(type: .helloAck); e.helloAck = h; return e }
    public static func reportAck(_ a: ReportAck) -> WireEnvelope { var e = WireEnvelope(type: .reportAck); e.reportAck = a; return e }
    public static func reveal(_ r: RevealRequest) -> WireEnvelope { var e = WireEnvelope(type: .revealSource); e.reveal = r; return e }
    public static func revealResult(_ r: RevealResult) -> WireEnvelope { var e = WireEnvelope(type: .revealResult); e.revealResult = r; return e }
    public static func error(code: String, message: String) -> WireEnvelope { var e = WireEnvelope(type: .error); e.error = WireError(code: code, message: message); return e }
}

public struct Frame: Sendable, Equatable {
    public var envelope: WireEnvelope
    public var body: Data

    public init(envelope: WireEnvelope, body: Data = Data()) {
        self.envelope = envelope
        self.body = body
    }

    /// A report frame with named binary parts appended to the body.
    public static func report(_ report: DebugReport, parts: [(name: String, data: Data)]) -> Frame {
        var e = WireEnvelope(type: .report)
        e.report = report
        e.parts = parts.map { PartDescriptor(name: $0.name, length: $0.data.count) }
        var body = Data()
        for p in parts { body.append(p.data) }
        return Frame(envelope: e, body: body)
    }

    /// Splits the body back into named parts using the envelope's descriptors.
    public func splitParts() throws -> [String: Data] {
        guard let descriptors = envelope.parts else { return [:] }
        var out: [String: Data] = [:]
        var offset = body.startIndex
        for d in descriptors {
            guard d.length >= 0, body.distance(from: offset, to: body.endIndex) >= d.length else { throw FrameError.malformedParts }
            let end = body.index(offset, offsetBy: d.length)
            guard out[d.name] == nil else { throw FrameError.malformedParts }
            out[d.name] = Data(body[offset..<end])
            offset = end
        }
        guard offset == body.endIndex else { throw FrameError.malformedParts }
        return out
    }
}

public enum FrameError: Error, Equatable, CustomStringConvertible {
    case headerTooLarge(Int)
    case bodyTooLarge(Int)
    case malformedHeader(String)
    case malformedParts

    public var description: String {
        switch self {
        case .headerTooLarge(let n): return "Frame header too large (\(n) bytes)."
        case .bodyTooLarge(let n): return "Frame body too large (\(n) bytes)."
        case .malformedHeader(let s): return "Malformed frame header: \(s)"
        case .malformedParts: return "Frame parts do not match the body."
        }
    }
}

/// Frame layout: `[UInt32 BE header length][UInt32 BE body length][header JSON][body]`.
public enum FrameCodec {
    public static let maxHeaderBytes = 4 * 1024 * 1024
    public static let maxBodyBytes = 64 * 1024 * 1024

    public static func encode(_ frame: Frame) throws -> Data {
        let header = try ReportCoding.encoder().encode(frame.envelope)
        guard header.count <= maxHeaderBytes else { throw FrameError.headerTooLarge(header.count) }
        guard frame.body.count <= maxBodyBytes else { throw FrameError.bodyTooLarge(frame.body.count) }
        var out = Data(capacity: 8 + header.count + frame.body.count)
        out.append(contentsOf: withUnsafeBytes(of: UInt32(header.count).bigEndian, Array.init))
        out.append(contentsOf: withUnsafeBytes(of: UInt32(frame.body.count).bigEndian, Array.init))
        out.append(header)
        out.append(frame.body)
        return out
    }
}

/// Incremental decoder for a byte stream of frames.
public struct FrameDecoder: Sendable {
    private var buffer = Data()

    public init() {}

    public mutating func append(_ data: Data) throws -> [Frame] {
        buffer.append(data)
        var frames: [Frame] = []
        while buffer.count >= 8 {
            let bytes = [UInt8](buffer.prefix(8))
            let headerLen = Int(UInt32(bytes[0]) << 24 | UInt32(bytes[1]) << 16 | UInt32(bytes[2]) << 8 | UInt32(bytes[3]))
            let bodyLen = Int(UInt32(bytes[4]) << 24 | UInt32(bytes[5]) << 16 | UInt32(bytes[6]) << 8 | UInt32(bytes[7]))
            guard headerLen <= FrameCodec.maxHeaderBytes else { throw FrameError.headerTooLarge(headerLen) }
            guard bodyLen <= FrameCodec.maxBodyBytes else { throw FrameError.bodyTooLarge(bodyLen) }
            guard buffer.count >= 8 + headerLen + bodyLen else { break }
            let start = buffer.startIndex
            let headerData = buffer.subdata(in: (start + 8)..<(start + 8 + headerLen))
            let body = buffer.subdata(in: (start + 8 + headerLen)..<(start + 8 + headerLen + bodyLen))
            buffer.removeSubrange(start..<(start + 8 + headerLen + bodyLen))
            buffer = Data(buffer) // re-base indices
            let envelope: WireEnvelope
            do {
                envelope = try ReportCoding.decoder().decode(WireEnvelope.self, from: headerData)
            } catch {
                throw FrameError.malformedHeader(String(describing: error))
            }
            frames.append(Frame(envelope: envelope, body: body))
        }
        return frames
    }

    public var bufferedByteCount: Int { buffer.count }
}
#endif
